"""
Read pages a model chose over plain HTTP, with the cookies of the browser session that signed in (AGENT_HTTP_READ=1).

The four websites render their pages on the server, so a GET with the session's cookies returns the same content a
browser tab shows, in about 0.1 to 0.3 s instead of a page load, settle and walk (1 to 5 s, much more when a site is
slow). Only reading happens here: the model still chooses every address (a link target it has seen on a page), and
signing in, consent, entry gates, forms, the bid wizard and signing stay in the browser.

`html_view` turns HTML into the same kind of text `extract.observe` gives, minus refs: hidden elements dropped (the
`hidden` attribute, `aria-hidden`, inline and stylesheet `display:none` / `visibility:hidden`, closed dialogs),
collapsed `<details>` shown, tooltips and image/canvas labels inlined, links as `[link "text" -> target]`, same-site
iframes fetched and shown in place, zero-width characters stripped.

A page that needs the browser comes back as None and the caller opens it in its tab as before: a redirect to
another page (a sign-in, a consent or entry gate), an error status or error page after a retry, an empty body, or a
request that times out. The browser's cookies are read again after every such miss, so a tab that signs in again
or passes a gate also renews the reader.
"""
import asyncio
import os
import re
import time
from dataclasses import dataclass, field
from html.parser import HTMLParser
from urllib.parse import urljoin, urlparse

HTTP_READ = os.environ.get("AGENT_HTTP_READ", "0") == "1"
FETCH_SECONDS = float(os.environ.get("HTTP_READ_SECONDS", "10"))  # one request; a stalled one goes to the browser
PARALLEL = int(os.environ.get("HTTP_READ_PARALLEL", "6"))  # requests at once per website
FRAME_DEPTH = 2  # nested iframes fetched in place (the tender Q&A nests two)
RETRY_WAIT = 0.6  # seconds before the one retry of an error page
MIN_TEXT = 40  # characters of body text below which a page counts as empty (needs scripts, or a blank error)

ERROR_PAGE = re.compile(r"vorübergehend nicht verfügbar|temporarily unavailable|service unavailable|bad gateway|"
                        r"gateway time-?out|internal server error", re.IGNORECASE)
ZW = re.compile("[\u200b\u200c\u200d\u2060\ufeff\u00ad]")
VOID = {"area", "base", "br", "col", "embed", "hr", "img", "input", "link", "meta", "param", "source", "track", "wbr"}
SKIP = {"script", "style", "noscript", "template", "head", "meta", "link", "title"}
BLOCK = {"address", "article", "aside", "blockquote", "body", "caption", "dd", "details", "dialog", "div", "dl", "dt",
         "fieldset", "figcaption", "figure", "footer", "form", "h1", "h2", "h3", "h4", "h5", "h6", "header", "hr",
         "legend", "li", "main", "nav", "ol", "p", "pre", "section", "summary", "table", "tbody", "thead", "tfoot",
         "tr", "ul", "br", "label"}
# end tags a parser closes implicitly when a sibling of the same kind starts
IMPLIED = {"p": {"p"}, "li": {"li"}, "tr": {"tr"}, "td": {"td", "th"}, "th": {"td", "th"}, "option": {"option"},
           "dt": {"dt", "dd"}, "dd": {"dt", "dd"}}


@dataclass
class Node:
    tag: str
    attrs: dict[str, str]
    parent: "Node | None" = None
    children: list = field(default_factory=list)  # Node or str

    def text(self) -> str:
        return "".join(c if isinstance(c, str) else c.text() for c in self.children)

    def classes(self) -> set[str]:
        return set(self.attrs.get("class", "").split())


class _Tree(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.root = Node("#root", {})
        self.cur = self.root

    def handle_starttag(self, tag, attrs):
        closes = IMPLIED.get(tag)
        if closes:  # <p>a<p>b: the second p closes the first (only up to the nearest block boundary)
            node = self.cur
            while node is not self.root and node.tag not in ("table", "ul", "ol", "select", "div", "body", "dl"):
                if node.tag in closes:
                    self.cur = node.parent or self.root
                    break
                node = node.parent
        node = Node(tag, {k: (v if v is not None else "") for k, v in attrs}, self.cur)
        self.cur.children.append(node)
        if tag not in VOID:
            self.cur = node

    def handle_startendtag(self, tag, attrs):
        self.cur.children.append(Node(tag, {k: (v if v is not None else "") for k, v in attrs}, self.cur))

    def handle_endtag(self, tag):
        node = self.cur
        while node is not self.root and node.tag != tag:
            node = node.parent
        if node is not self.root:
            self.cur = node.parent or self.root

    def handle_data(self, data):
        self.cur.children.append(data)


# ---- the few stylesheet rules that hide things: compound selectors and descendant chains of them ----

_COMPOUND = re.compile(r"^([a-zA-Z][\w-]*|\*)?((?:[#.][\w-]+|\[[^\]]+\])*)$")
_PARTS = re.compile(r"[#.][\w-]+|\[[^\]]+\]")
_PSEUDO = re.compile(r":{1,2}[\w-]+(?:\([^)]*\))?")
_HIDES = re.compile(r"display\s*:\s*none|visibility\s*:\s*(?:hidden|collapse)", re.IGNORECASE)
_SHOWS = re.compile(r"display\s*:\s*(?!none)[\w-]+|visibility\s*:\s*visible", re.IGNORECASE)


def _compound(text: str):
    m = _COMPOUND.match(text)
    if not m:
        return None
    tag = (m.group(1) or "*").lower()
    parts = []
    for part in _PARTS.findall(m.group(2) or ""):
        if part[0] == "#":
            parts.append(("id", part[1:]))
        elif part[0] == ".":
            parts.append(("class", part[1:]))
        else:
            inner = part[1:-1]
            name, op, value = re.match(r"\s*([\w-]+)\s*(?:([~|^$*]?=)\s*['\"]?([^'\"]*)['\"]?)?\s*$", inner).groups() \
                if re.match(r"\s*[\w-]+", inner) else (None, None, None)
            if name is None:
                return None
            parts.append(("attr", (name.lower(), op, value)))
    return tag, parts


def _matches(node: Node, compound) -> bool:
    tag, parts = compound
    if tag != "*" and node.tag != tag:
        return False
    for kind, value in parts:
        if kind == "id" and node.attrs.get("id") != value:
            return False
        if kind == "class" and value not in node.classes():
            return False
        if kind == "attr":
            name, op, want = value
            if name not in node.attrs:
                return False
            have = node.attrs[name]
            if op == "=" and have != want or op == "~=" and want not in have.split() \
                    or op == "^=" and not have.startswith(want) or op == "$=" and not have.endswith(want) \
                    or op == "*=" and want not in have:
                return False
    return True


class Hider:
    """Selectors of the page's stylesheets whose rules hide elements (and are not undone by a :hover/:focus rule of
    the same selector, e.g. a dropdown menu: those stay visible, as a person can open them)."""

    def __init__(self, css: str):
        hide, show = [], set()
        css = re.sub(r"/\*.*?\*/", "", css, flags=re.S)
        css = re.sub(r"@media[^{]*\{((?:[^{}]*\{[^{}]*\})*)\s*\}", "", css)  # screen-size variants: ignored
        for selectors, body in re.findall(r"([^{}]+)\{([^{}]*)\}", css):
            for sel in selectors.split(","):
                sel = " ".join(sel.split())
                if not sel or sel.startswith("@"):
                    continue
                if _HIDES.search(body):
                    if not _PSEUDO.search(sel):
                        hide.append(sel)
                elif _SHOWS.search(body) and _PSEUDO.search(sel):
                    show.add(" ".join(_PSEUDO.sub("", sel).split()))
        self.rules = []
        for sel in hide:
            if sel in show or any(c in sel for c in ">+~"):
                continue
            chain = [_compound(p) for p in sel.split(" ")]
            if all(chain):
                self.rules.append(chain)

    def hides(self, node: Node) -> bool:
        for chain in self.rules:
            if not _matches(node, chain[-1]):
                continue
            want, up = len(chain) - 2, node.parent
            while want >= 0 and up is not None:
                if up.tag != "#root" and _matches(up, chain[want]):
                    want -= 1
                up = up.parent
            if want < 0:
                return True
        return False


def _clean(text: str) -> str:
    return " ".join(ZW.sub("", text or "").split())


def _style_hidden(style: str) -> bool:
    return bool(_HIDES.search(style or ""))


@dataclass
class HtmlView:
    title: str
    text: str
    frames: list[str]  # iframe sources, in order (fetched by the reader and put in place)
    links: list[str]


def html_view(html: str) -> HtmlView:
    """The page's visible content as text, as the browser view shows it but without refs (see module doc)."""
    tree = _Tree()
    tree.feed(html)
    tree.close()
    root = tree.root
    styles, titles = [], []

    def gather(node: Node) -> None:
        for c in node.children:
            if isinstance(c, Node):
                if c.tag == "style":
                    styles.append(c.text())
                elif c.tag == "title" and not titles:
                    titles.append(_clean(c.text()))
                else:
                    gather(c)
    gather(root)
    hider = Hider("\n".join(styles))
    out: list[str] = []
    frames: list[str] = []
    links: list[str] = []
    emit = out.append

    def label_of(node: Node) -> str:
        for key in ("aria-label", "title", "placeholder", "name"):
            if node.attrs.get(key):
                return _clean(node.attrs[key])
        if node.attrs.get("id"):
            label = _labels.get(node.attrs["id"])
            if label:
                return label
        up = node.parent
        while up is not None and up.tag != "#root":
            if up.tag == "label":
                return _clean(_own_text(up))
            up = up.parent
        return ""

    def _own_text(node: Node) -> str:
        return "".join(c if isinstance(c, str) else ("" if c.tag in ("select", "option", "input", "textarea",
                                                                       "button", "style", "script")
                                                      else _own_text(c)) for c in node.children)

    _labels: dict[str, str] = {}

    def index_labels(node: Node) -> None:
        for c in node.children:
            if isinstance(c, Node):
                if c.tag == "label" and c.attrs.get("for"):
                    _labels[c.attrs["for"]] = _clean(_own_text(c))
                index_labels(c)
    index_labels(root)

    def hidden(node: Node) -> bool:
        a = node.attrs
        if "hidden" in a or a.get("aria-hidden") == "true" or _style_hidden(a.get("style", "")):
            return True
        if node.tag == "dialog" and "open" not in a:  # closed dialogs are not rendered; pop-ups open by script
            return True
        if node.tag == "input" and a.get("type", "").lower() == "hidden":
            return True
        return hider.hides(node)

    def control(node: Node) -> str:
        a, tag = node.attrs, node.tag
        if tag == "select":
            opts = [c for c in _descendants(node) if c.tag == "option"]
            chosen = [o for o in opts if "selected" in o.attrs] or opts[:1]
            names = [_clean(o.text()) for o in opts]
            listing = " | ".join(names) if len(" | ".join(names)) <= 600 else \
                " | ".join(names[:8]) + f" | ... {len(names) - 10} more ... | " + " | ".join(names[-2:])
            return (f'[select "{label_of(node)}" name={a.get("name", "")} selected="{_clean(chosen[0].text()) if chosen else ""}"'
                    f" options: {listing}]")
        if tag == "textarea":
            return f'[textarea "{label_of(node)}" name={a.get("name", "")}]'
        if tag == "button" or (tag == "input" and a.get("type", "").lower() in ("submit", "button", "reset", "image")):
            name = _clean(node.text()) or _clean(a.get("value", "")) or label_of(node)
            target = a.get("data-url") or a.get("formaction") or ""
            return f'[button "{name}"' + (f" -> {target}" if target else "") + "]"
        kind = a.get("type", "text").lower()
        if kind in ("checkbox", "radio"):
            return f'[{kind} "{label_of(node)}" {"checked" if "checked" in a else "unchecked"}]'
        if kind == "range":
            return f'[slider "{label_of(node)}" value={a.get("value", "")}]'
        value = "" if kind == "password" else _clean(a.get("value", ""))
        return f'[textbox "{label_of(node)}" name={a.get("name", "")} value="{value}"]'

    def walk(node: Node, pre: bool = False) -> None:
        for c in node.children:
            if isinstance(c, str):
                raw = ZW.sub("", c)
                t = raw.replace("\n", "\u2028") if pre else re.sub(r"\s+", " ", raw)
                if t.strip():
                    emit(t)
                continue
            tag, a = c.tag, c.attrs
            if tag in SKIP:
                continue
            if a.get("role") == "tooltip":
                if "hidden" not in a and a.get("aria-hidden") != "true":
                    emit(f" (tooltip: {_clean(c.text())}) ")
                continue
            if hidden(c):
                continue
            if tag in ("canvas", "img", "svg") or a.get("role") == "img":
                label = _clean(a.get("aria-label") or a.get("alt") or a.get("title") or "")
                if label:
                    emit(f" [img: {label}] ")
                continue
            if tag in ("iframe", "frame"):
                src = a.get("src", "")
                frames.append(src)
                emit(f"\n[frame {src}]\n\x00FRAME{len(frames) - 1}\x00\n[/frame]\n")
                continue
            block = tag in BLOCK
            if block:
                emit("\n")
            if re.fullmatch(r"h[1-6]", tag):
                emit("#" * int(tag[1]) + " ")
            if tag == "li":
                emit("- ")
            if tag == "a" and "href" in a:
                name = _clean(c.text()) or label_of(c) or _clean(" ".join(
                    d.attrs.get("aria-label", "") for d in _descendants(c)))
                links.append(a["href"])
                emit(f' [link "{name}" -> {a["href"]}] ')
            elif tag in ("button", "select", "textarea", "input"):
                emit(" " + control(c) + " ")
            elif tag == "form":
                method = a.get("method", "get").lower()
                emit(f"[form {method.upper()} -> {a.get('action', '')}]\n")
                walk(c, pre)
                if method == "get":  # a search form: its fields name the query string a reader can open
                    fields = [d for d in _descendants(c) if d.tag in ("input", "select", "textarea") and d.attrs.get("name")
                              and d.attrs.get("type", "").lower() not in ("submit", "button", "checkbox", "radio")]
                    if fields:
                        query = "&".join(f"{d.attrs['name']}={d.attrs.get('value', '') if d.tag == 'input' else ''}"
                                         for d in fields)
                        emit(f"\n[search address: {a.get('action', '') or '.'}?{query}]\n")
            else:
                walk(c, pre or tag == "pre")
                if tag == "time" and a.get("datetime"):
                    emit(f" (datetime={a['datetime']})")
                title = a.get("title")
                if title and _clean(title) not in _clean(c.text()):
                    emit(f" (title: {_clean(title)})")
            if tag in ("td", "th"):
                emit(" | ")
            if block:
                emit("\n")

    walk(root)
    text = "".join(out)
    text = re.sub(r"[ \t]+", " ", text)
    text = re.sub(r" *\n *", "\n", text)
    text = re.sub(r"\n{2,}", "\n", text).replace("\u2028", "\n").strip()
    return HtmlView(titles[0] if titles else "", text, frames, links)


def _descendants(node: Node):
    for c in node.children:
        if isinstance(c, Node):
            yield c
            yield from _descendants(c)


# ---- the reader: one HTTP client per browser context, with that context's cookies ----

@dataclass
class Fetched:
    url: str  # where the request ended (after redirects)
    title: str
    text: str  # the view text, frames in place
    seconds: float


class Miss(Exception):
    """The page needs the browser (a gate, a sign-in, an error, nothing to read)."""


class HttpReader:
    def __init__(self, context, site_url: str):
        import httpx2  # openai's HTTP client; honours HTTP(S)_PROXY like httpx
        self.context, self.site_url = context, site_url
        self.host = urlparse(site_url).netloc
        self.client = httpx2.AsyncClient(follow_redirects=True, timeout=FETCH_SECONDS, trust_env=True)
        self.limit = asyncio.Semaphore(PARALLEL)
        self.cache: dict[str, Fetched] = {}
        self.synced = 0.0
        self.agent = ""
        self.stats = {"fetched": 0, "cached": 0, "missed": 0, "seconds": 0.0}

    async def sync(self, force: bool = False) -> None:
        """The browser context's cookies for this site (and its User-Agent), read at most every few seconds."""
        if not force and time.monotonic() - self.synced < 5.0:
            return
        cookies = await asyncio.wait_for(self.context.cookies(self.site_url), 5)
        self.client.cookies.clear()
        for c in cookies:
            self.client.cookies.set(c["name"], c["value"], domain=c.get("domain", "").lstrip("."), path=c.get("path", "/"))
        if not self.agent:
            for page in self.context.pages:
                try:
                    self.agent = await asyncio.wait_for(page.evaluate("navigator.userAgent"), 3)
                    break
                except Exception:
                    continue
            self.client.headers["User-Agent"] = self.agent or "error404ai-agent/1.0"
        self.synced = time.monotonic()

    async def _get(self, url: str):
        async with self.limit:
            return await self.client.get(url, headers={"Accept": "text/html,*/*"})

    async def fetch(self, url: str, depth: int = 0) -> Fetched:
        """The page at `url` as view text; raises Miss when the browser has to open it."""
        if url in self.cache:
            self.stats["cached"] += 1
            return self.cache[url]
        if urlparse(url).netloc != self.host:
            raise Miss("not on this website")
        began = time.monotonic()
        await self.sync()
        response = None
        for attempt in range(2):
            try:
                response = await self._get(url)
            except Exception as error:
                if attempt:
                    raise Miss(f"request failed: {type(error).__name__}") from error
                await asyncio.sleep(RETRY_WAIT)
                continue
            body = response.text
            if response.status_code < 500 and not (len(body) < 20000 and ERROR_PAGE.search(body[:20000])):
                break
            if attempt:
                raise Miss(f"error page ({response.status_code})")
            await asyncio.sleep(RETRY_WAIT)
        assert response is not None
        final = str(response.url)
        if response.status_code >= 400:
            raise Miss(f"status {response.status_code}")
        if "html" not in response.headers.get("content-type", "html"):
            text = ZW.sub("", response.text)[:60000]
            fetched = Fetched(final, "", text, time.monotonic() - began)
            self.cache[url] = fetched
            return fetched
        wanted, landed = urlparse(url), urlparse(final)
        if (wanted.path.rstrip("/"), wanted.query) != (landed.path.rstrip("/"), landed.query) and \
                landed.path.rstrip("/") != wanted.path.rstrip("/"):
            await self.sync(force=True)  # perhaps the browser signed in again since: next time with its cookies
            raise Miss(f"redirected to {landed.path}")
        view = html_view(response.text)
        if re.search(r'type=["\']?password', response.text, re.IGNORECASE):
            await self.sync(force=True)
            raise Miss("a sign-in form")
        text = view.text
        if depth < FRAME_DEPTH and view.frames:
            subs = await asyncio.gather(*(self._frame(urljoin(final, src), depth) for src in view.frames))
            for i, sub in enumerate(subs):
                text = text.replace(f"\x00FRAME{i}\x00", sub)
        text = re.sub(r"\x00FRAME\d+\x00", "", text)
        text = re.sub(r"\n{2,}", "\n", text)
        if len(text) < MIN_TEXT:
            raise Miss("nothing to read without scripts")
        fetched = Fetched(final, view.title, text, time.monotonic() - began)
        self.cache[url] = fetched
        self.stats["fetched"] += 1
        self.stats["seconds"] += fetched.seconds
        return fetched

    async def _frame(self, url: str, depth: int) -> str:
        if not url.startswith("http") or urlparse(url).netloc != self.host:
            return "(separate)"
        try:
            return (await self.fetch(url, depth + 1)).text
        except Miss as miss:
            return f"(not read: {miss})"


_READERS: dict[tuple[int, str], HttpReader] = {}


def reader(session) -> HttpReader:
    """The HTTP reader of the session's browser context and website."""
    key = (id(session.context), urlparse(session.site["url"]).netloc)
    if key not in _READERS or _READERS[key].context is not session.context:
        _READERS[key] = HttpReader(session.context, session.site["url"])
    return _READERS[key]


def view_text(fetched: Fetched) -> str:
    """A fetched page in the format of SiteSession.look (header lines, blank line, page text)."""
    return f"URL: {fetched.url}\nTitle: {fetched.title}\n\n{fetched.text}"


def record(session, fetched: Fetched) -> None:
    """Let the session's grounding checks and view keepers see a page read over HTTP as if its tab showed it."""
    session.seen += "\n" + fetched.text
    session.trace.event(session.name, "view", quiet=True, url=fetched.url, text=fetched.text, http=True)
    for sink in session.__dict__.get("view_sinks", ()):
        sink(fetched.url, fetched.text)


async def fetch_view(session, url: str) -> str | None:
    """The page at `url` read over HTTP and recorded for the session, or None when the browser has to open it."""
    rd = reader(session)
    try:
        fetched = await rd.fetch(url)
    except Miss as miss:
        rd.stats["missed"] += 1
        session.trace.event(session.name, "http_miss", url=url[:160], why=str(miss)[:120])
        return None
    except Exception as error:  # never let the reader break a worker: the browser takes over
        rd.stats["missed"] += 1
        session.trace.event(session.name, "http_miss", url=url[:160], why=f"{type(error).__name__}: {str(error)[:100]}")
        return None
    record(session, fetched)
    session.trace.event(session.name, "http_read", url=url[:160], seconds=round(fetched.seconds, 2),
                        chars=len(fetched.text))
    return view_text(fetched)


async def fetch_many(session, urls: list[str]) -> dict[str, str | None]:
    """Several model-chosen pages at once (in their order); None for each page the browser has to open."""
    urls = list(dict.fromkeys(urls))
    views = await asyncio.gather(*(fetch_view(session, u) for u in urls))
    return dict(zip(urls, views))


def stats_line() -> str:
    """Totals over every reader of the run, for the run summary."""
    total = {"fetched": 0, "cached": 0, "missed": 0, "seconds": 0.0}
    for rd in _READERS.values():
        for k in total:
            total[k] += rd.stats[k]
    if not any(total.values()):
        return ""
    mean = total["seconds"] / total["fetched"] if total["fetched"] else 0.0
    return (f"http_read: {total['fetched']} pages fetched (mean {mean:.2f} s), {total['cached']} from cache, "
            f"{total['missed']} handed to the browser")

toolUseResult.content:
"""
Read pages a model chose over plain HTTP, with the cookies of the browser session that signed in (AGENT_HTTP_READ=1).

The four websites render their pages on the server, so a GET with the session's cookies returns the same content a
browser tab shows, in about 0.1 to 0.3 s instead of a page load, settle and walk (1 to 5 s, much more when a site is
slow). Only reading happens here: the model still chooses every address (a link target it has seen on a page), and
signing in, consent, entry gates, forms, the bid wizard and signing stay in the browser.

`html_view` turns HTML into the same kind of text `extract.observe` gives, minus refs: hidden elements dropped (the
`hidden` attribute, `aria-hidden`, inline and stylesheet `display:none` / `visibility:hidden`, closed dialogs),
collapsed `<details>` shown, tooltips and image/canvas labels inlined, links as `[link "text" -> target]`, same-site
iframes fetched and shown in place, zero-width characters stripped.

A page that needs the browser comes back as None and the caller opens it in its tab as before: a redirect to
another page (a sign-in, a consent or entry gate), an error status or error page after a retry, an empty body, or a
request that times out. The browser's cookies are read again after every such miss, so a tab that signs in again
or passes a gate also renews the reader.
"""
import asyncio
import os
import re
import time
from dataclasses import dataclass, field
from html.parser import HTMLParser
from urllib.parse import urljoin, urlparse

HTTP_READ = os.environ.get("AGENT_HTTP_READ", "0") == "1"
FETCH_SECONDS = float(os.environ.get("HTTP_READ_SECONDS", "10"))  # one request; a stalled one goes to the browser
PARALLEL = int(os.environ.get("HTTP_READ_PARALLEL", "6"))  # requests at once per website
FRAME_DEPTH = 2  # nested iframes fetched in place (the tender Q&A nests two)
RETRY_WAIT = 0.6  # seconds before the one retry of an error page
MIN_TEXT = 40  # characters of body text below which a page counts as empty (needs scripts, or a blank error)

ERROR_PAGE = re.compile(r"vorübergehend nicht verfügbar|temporarily unavailable|service unavailable|bad gateway|"
                        r"gateway time-?out|internal server error", re.IGNORECASE)
ZW = re.compile("[​‌‍⁠﻿­]")
VOID = {"area", "base", "br", "col", "embed", "hr", "img", "input", "link", "meta", "param", "source", "track", "wbr"}
SKIP = {"script", "style", "noscript", "template", "head", "meta", "link", "title"}
BLOCK = {"address", "article", "aside", "blockquote", "body", "caption", "dd", "details", "dialog", "div", "dl", "dt",
         "fieldset", "figcaption", "figure", "footer", "form", "h1", "h2", "h3", "h4", "h5", "h6", "header", "hr",
         "legend", "li", "main", "nav", "ol", "p", "pre", "section", "summary", "table", "tbody", "thead", "tfoot",
         "tr", "ul", "br", "label"}
# end tags a parser closes implicitly when a sibling of the same kind starts
IMPLIED = {"p": {"p"}, "li": {"li"}, "tr": {"tr"}, "td": {"td", "th"}, "th": {"td", "th"}, "option": {"option"},
           "dt": {"dt", "dd"}, "dd": {"dt", "dd"}}


@dataclass
class Node:
    tag: str
    attrs: dict[str, str]
    parent: "Node | None" = None
    children: list = field(default_factory=list)  # Node or str

    def text(self) -> str:
        return "".join(c if isinstance(c, str) else c.text() for c in self.children)

    def classes(self) -> set[str]:
        return set(self.attrs.get("class", "").split())


class _Tree(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.root = Node("#root", {})
        self.cur = self.root

    def handle_starttag(self, tag, attrs):
        closes = IMPLIED.get(tag)
        if closes:  # <p>a<p>b: the second p closes the first (only up to the nearest block boundary)
            node = self.cur
            while node is not self.root and node.tag not in ("table", "ul", "ol", "select", "div", "body", "dl"):
                if node.tag in closes:
                    self.cur = node.parent or self.root
                    break
                node = node.parent
        node = Node(tag, {k: (v if v is not None else "") for k, v in attrs}, self.cur)
        self.cur.children.append(node)
        if tag not in VOID:
            self.cur = node

    def handle_startendtag(self, tag, attrs):
        self.cur.children.append(Node(tag, {k: (v if v is not None else "") for k, v in attrs}, self.cur))

    def handle_endtag(self, tag):
        node = self.cur
        while node is not self.root and node.tag != tag:
            node = node.parent
        if node is not self.root:
            self.cur = node.parent or self.root

    def handle_data(self, data):
        self.cur.children.append(data)


# ---- the few stylesheet rules that hide things: compound selectors and descendant chains of them ----

_COMPOUND = re.compile(r"^([a-zA-Z][\w-]*|\*)?((?:[#.][\w-]+|\[[^\]]+\])*)$")
_PARTS = re.compile(r"[#.][\w-]+|\[[^\]]+\]")
_PSEUDO = re.compile(r":{1,2}[\w-]+(?:\([^)]*\))?")
_HIDES = re.compile(r"display\s*:\s*none|visibility\s*:\s*(?:hidden|collapse)", re.IGNORECASE)
_SHOWS = re.compile(r"display\s*:\s*(?!none)[\w-]+|visibility\s*:\s*visible", re.IGNORECASE)


def _compound(text: str):
    m = _COMPOUND.match(text)
    if not m:
        return None
    tag = (m.group(1) or "*").lower()
    parts = []
    for part in _PARTS.findall(m.group(2) or ""):
        if part[0] == "#":
            parts.append(("id", part[1:]))
        elif part[0] == ".":
            parts.append(("class", part[1:]))
        else:
            inner = part[1:-1]
            name, op, value = re.match(r"\s*([\w-]+)\s*(?:([~|^$*]?=)\s*['\"]?([^'\"]*)['\"]?)?\s*$", inner).groups() \
                if re.match(r"\s*[\w-]+", inner) else (None, None, None)
            if name is None:
                return None
            parts.append(("attr", (name.lower(), op, value)))
    return tag, parts


def _matches(node: Node, compound) -> bool:
    tag, parts = compound
    if tag != "*" and node.tag != tag:
        return False
    for kind, value in parts:
        if kind == "id" and node.attrs.get("id") != value:
            return False
        if kind == "class" and value not in node.classes():
            return False
        if kind == "attr":
            name, op, want = value
            if name not in node.attrs:
                return False
            have = node.attrs[name]
            if op == "=" and have != want or op == "~=" and want not in have.split() \
                    or op == "^=" and not have.startswith(want) or op == "$=" and not have.endswith(want) \
                    or op == "*=" and want not in have:
                return False
    return True


class Hider:
    """Selectors of the page's stylesheets whose rules hide elements (and are not undone by a :hover/:focus rule of
    the same selector, e.g. a dropdown menu: those stay visible, as a person can open them)."""

    def __init__(self, css: str):
        hide, show = [], set()
        css = re.sub(r"/\*.*?\*/", "", css, flags=re.S)
        css = re.sub(r"@media[^{]*\{((?:[^{}]*\{[^{}]*\})*)\s*\}", "", css)  # screen-size variants: ignored
        for selectors, body in re.findall(r"([^{}]+)\{([^{}]*)\}", css):
            for sel in selectors.split(","):
                sel = " ".join(sel.split())
                if not sel or sel.startswith("@"):
                    continue
                if _HIDES.search(body):
                    if not _PSEUDO.search(sel):
                        hide.append(sel)
                elif _SHOWS.search(body) and _PSEUDO.search(sel):
                    show.add(" ".join(_PSEUDO.sub("", sel).split()))
        self.rules = []
        for sel in hide:
            if sel in show or any(c in sel for c in ">+~"):
                continue
            chain = [_compound(p) for p in sel.split(" ")]
            if all(chain):
                self.rules.append(chain)

    def hides(self, node: Node) -> bool:
        for chain in self.rules:
            if not _matches(node, chain[-1]):
                continue
            want, up = len(chain) - 2, node.parent
            while want >= 0 and up is not None:
                if up.tag != "#root" and _matches(up, chain[want]):
                    want -= 1
                up = up.parent
            if want < 0:
                return True
        return False


def _clean(text: str) -> str:
    return " ".join(ZW.sub("", text or "").split())


def _style_hidden(style: str) -> bool:
    return bool(_HIDES.search(style or ""))


@dataclass
class HtmlView:
    title: str
    text: str
    frames: list[str]  # iframe sources, in order (fetched by the reader and put in place)
    links: list[str]


def html_view(html: str) -> HtmlView:
    """The page's visible content as text, as the browser view shows it but without refs (see module doc)."""
    tree = _Tree()
    tree.feed(html)
    tree.close()
    root = tree.root
    styles, titles = [], []

    def gather(node: Node) -> None:
        for c in node.children:
            if isinstance(c, Node):
                if c.tag == "style":
                    styles.append(c.text())
                elif c.tag == "title" and not titles:
                    titles.append(_clean(c.text()))
                else:
                    gather(c)
    gather(root)
    hider = Hider("\n".join(styles))
    out: list[str] = []
    frames: list[str] = []
    links: list[str] = []
    emit = out.append

    def label_of(node: Node) -> str:
        for key in ("aria-label", "title", "placeholder", "name"):
            if node.attrs.get(key):
                return _clean(node.attrs[key])
        if node.attrs.get("id"):
            label = _labels.get(node.attrs["id"])
            if label:
                return label
        up = node.parent
        while up is not None and up.tag != "#root":
            if up.tag == "label":
                return _clean(_own_text(up))
            up = up.parent
        return ""

    def _own_text(node: Node) -> str:
        return "".join(c if isinstance(c, str) else ("" if c.tag in ("select", "option", "input", "textarea",
                                                                       "button", "style", "script")
                                                      else _own_text(c)) for c in node.children)

    _labels: dict[str, str] = {}

    def index_labels(node: Node) -> None:
        for c in node.children:
            if isinstance(c, Node):
                if c.tag == "label" and c.attrs.get("for"):
                    _labels[c.attrs["for"]] = _clean(_own_text(c))
                index_labels(c)
    index_labels(root)

    def hidden(node: Node) -> bool:
        a = node.attrs
        if "hidden" in a or a.get("aria-hidden") == "true" or _style_hidden(a.get("style", "")):
            return True
        if node.tag == "dialog" and "open" not in a:  # closed dialogs are not rendered; pop-ups open by script
            return True
        if node.tag == "input" and a.get("type", "").lower() == "hidden":
            return True
        return hider.hides(node)

    def control(node: Node) -> str:
        a, tag = node.attrs, node.tag
        if tag == "select":
            opts = [c for c in _descendants(node) if c.tag == "option"]
            chosen = [o for o in opts if "selected" in o.attrs] or opts[:1]
            names = [_clean(o.text()) for o in opts]
            listing = " | ".join(names) if len(" | ".join(names)) <= 600 else \
                " | ".join(names[:8]) + f" | ... {len(names) - 10} more ... | " + " | ".join(names[-2:])
            return (f'[select "{label_of(node)}" name={a.get("name", "")} selected="{_clean(chosen[0].text()) if chosen else ""}"'
                    f" options: {listing}]")
        if tag == "textarea":
            return f'[textarea "{label_of(node)}" name={a.get("name", "")}]'
        if tag == "button" or (tag == "input" and a.get("type", "").lower() in ("submit", "button", "reset", "image")):
            name = _clean(node.text()) or _clean(a.get("value", "")) or label_of(node)
            target = a.get("data-url") or a.get("formaction") or ""
            return f'[button "{name}"' + (f" -> {target}" if target else "") + "]"
        kind = a.get("type", "text").lower()
        if kind in ("checkbox", "radio"):
            return f'[{kind} "{label_of(node)}" {"checked" if "checked" in a else "unchecked"}]'
        if kind == "range":
            return f'[slider "{label_of(node)}" value={a.get("value", "")}]'
        value = "" if kind == "password" else _clean(a.get("value", ""))
        return f'[textbox "{label_of(node)}" name={a.get("name", "")} value="{value}"]'

    def walk(node: Node, pre: bool = False) -> None:
        for c in node.children:
            if isinstance(c, str):
                raw = ZW.sub("", c)
                t = raw.replace("\n", " ") if pre else re.sub(r"\s+", " ", raw)
                if t.strip():
                    emit(t)
                continue
            tag, a = c.tag, c.attrs
            if tag in SKIP:
                continue
            if a.get("role") == "tooltip":
                if "hidden" not in a and a.get("aria-hidden") != "true":
                    emit(f" (tooltip: {_clean(c.text())}) ")
                continue
            if hidden(c):
                continue
            if tag in ("canvas", "img", "svg") or a.get("role") == "img":
                label = _clean(a.get("aria-label") or a.get("alt") or a.get("title") or "")
                if label:
                    emit(f" [img: {label}] ")
                continue
            if tag in ("iframe", "frame"):
                src = a.get("src", "")
                frames.append(src)
                emit(f"\n[frame {src}]\n\x00FRAME{len(frames) - 1}\x00\n[/frame]\n")
                continue
            block = tag in BLOCK
            if block:
                emit("\n")
            if re.fullmatch(r"h[1-6]", tag):
                emit("#" * int(tag[1]) + " ")
            if tag == "li":
                emit("- ")
            if tag == "a" and "href" in a:
                name = _clean(c.text()) or label_of(c) or _clean(" ".join(
                    d.attrs.get("aria-label", "") for d in _descendants(c)))
                links.append(a["href"])
                emit(f' [link "{name}" -> {a["href"]}] ')
            elif tag in ("button", "select", "textarea", "input"):
                emit(" " + control(c) + " ")
            elif tag == "form":
                method = a.get("method", "get").lower()
                emit(f"[form {method.upper()} -> {a.get('action', '')}]\n")
                walk(c, pre)
                if method == "get":  # a search form: its fields name the query string a reader can open
                    fields = [d for d in _descendants(c) if d.tag in ("input", "select", "textarea") and d.attrs.get("name")
                              and d.attrs.get("type", "").lower() not in ("submit", "button", "checkbox", "radio")]
                    if fields:
                        query = "&".join(f"{d.attrs['name']}={d.attrs.get('value', '') if d.tag == 'input' else ''}"
                                         for d in fields)
                        emit(f"\n[search address: {a.get('action', '') or '.'}?{query}]\n")
            else:
                walk(c, pre or tag == "pre")
                if tag == "time" and a.get("datetime"):
                    emit(f" (datetime={a['datetime']})")
                title = a.get("title")
                if title and _clean(title) not in _clean(c.text()):
                    emit(f" (title: {_clean(title)})")
            if tag in ("td", "th"):
                emit(" | ")
            if block:
                emit("\n")

    walk(root)
    text = "".join(out)
    text = re.sub(r"[ \t]+", " ", text)
    text = re.sub(r" *\n *", "\n", text)
    text = re.sub(r"\n{2,}", "\n", text).replace(" ", "\n").strip()
    return HtmlView(titles[0] if titles else "", text, frames, links)


def _descendants(node: Node):
    for c in node.children:
        if isinstance(c, Node):
            yield c
            yield from _descendants(c)


# ---- the reader: one HTTP client per browser context, with that context's cookies ----

@dataclass
class Fetched:
    url: str  # where the request ended (after redirects)
    title: str
    text: str  # the view text, frames in place
    seconds: float


class Miss(Exception):
    """The page needs the browser (a gate, a sign-in, an error, nothing to read)."""


class HttpReader:
    def __init__(self, context, site_url: str):
        import httpx2  # openai's HTTP client; honours HTTP(S)_PROXY like httpx
        self.context, self.site_url = context, site_url
        self.host = urlparse(site_url).netloc
        self.client = httpx2.AsyncClient(follow_redirects=True, timeout=FETCH_SECONDS, trust_env=True)
        self.limit = asyncio.Semaphore(PARALLEL)
        self.cache: dict[str, Fetched] = {}
        self.synced = 0.0
        self.agent = ""
        self.stats = {"fetched": 0, "cached": 0, "missed": 0, "seconds": 0.0}

    async def sync(self, force: bool = False) -> None:
        """The browser context's cookies for this site (and its User-Agent), read at most every few seconds."""
        if not force and time.monotonic() - self.synced < 5.0:
            return
        cookies = await asyncio.wait_for(self.context.cookies(self.site_url), 5)
        self.client.cookies.clear()
        for c in cookies:
            self.client.cookies.set(c["name"], c["value"], domain=c.get("domain", "").lstrip("."), path=c.get("path", "/"))
        if not self.agent:
            for page in self.context.pages:
                try:
                    self.agent = await asyncio.wait_for(page.evaluate("navigator.userAgent"), 3)
                    break
                except Exception:
                    continue
            self.client.headers["User-Agent"] = self.agent or "error404ai-agent/1.0"
        self.synced = time.monotonic()

    async def _get(self, url: str):
        async with self.limit:
            return await self.client.get(url, headers={"Accept": "text/html,*/*"})

    async def fetch(self, url: str, depth: int = 0) -> Fetched:
        """The page at `url` as view text; raises Miss when the browser has to open it."""
        if url in self.cache:
            self.stats["cached"] += 1
            return self.cache[url]
        if urlparse(url).netloc != self.host:
            raise Miss("not on this website")
        began = time.monotonic()
        await self.sync()
        response = None
        for attempt in range(2):
            try:
                response = await self._get(url)
            except Exception as error:
                if attempt:
                    raise Miss(f"request failed: {type(error).__name__}") from error
                await asyncio.sleep(RETRY_WAIT)
                continue
            body = response.text
            if response.status_code < 500 and not (len(body) < 20000 and ERROR_PAGE.search(body[:20000])):
                break
            if attempt:
                raise Miss(f"error page ({response.status_code})")
            await asyncio.sleep(RETRY_WAIT)
        assert response is not None
        final = str(response.url)
        if response.status_code >= 400:
            raise Miss(f"status {response.status_code}")
        if "html" not in response.headers.get("content-type", "html"):
            text = ZW.sub("", response.text)[:60000]
            fetched = Fetched(final, "", text, time.monotonic() - began)
            self.cache[url] = fetched
            return fetched
        wanted, landed = urlparse(url), urlparse(final)
        if (wanted.path.rstrip("/"), wanted.query) != (landed.path.rstrip("/"), landed.query) and \
                landed.path.rstrip("/") != wanted.path.rstrip("/"):
            await self.sync(force=True)  # perhaps the browser signed in again since: next time with its cookies
            raise Miss(f"redirected to {landed.path}")
        view = html_view(response.text)
        if re.search(r'type=["\']?password', response.text, re.IGNORECASE):
            await self.sync(force=True)
            raise Miss("a sign-in form")
        text = view.text
        if depth < FRAME_DEPTH and view.frames:
            subs = await asyncio.gather(*(self._frame(urljoin(final, src), depth) for src in view.frames))
            for i, sub in enumerate(subs):
                text = text.replace(f"\x00FRAME{i}\x00", sub)
        text = re.sub(r"\x00FRAME\d+\x00", "", text)
        text = re.sub(r"\n{2,}", "\n", text)
        if len(text) < MIN_TEXT:
            raise Miss("nothing to read without scripts")
        fetched = Fetched(final, view.title, text, time.monotonic() - began)
        self.cache[url] = fetched
        self.stats["fetched"] += 1
        self.stats["seconds"] += fetched.seconds
        return fetched

    async def _frame(self, url: str, depth: int) -> str:
        if not url.startswith("http") or urlparse(url).netloc != self.host:
            return "(separate)"
        try:
            return (await self.fetch(url, depth + 1)).text
        except Miss as miss:
            return f"(not read: {miss})"


_READERS: dict[tuple[int, str], HttpReader] = {}


def reader(session) -> HttpReader:
    """The HTTP reader of the session's browser context and website."""
    key = (id(session.context), urlparse(session.site["url"]).netloc)
    if key not in _READERS or _READERS[key].context is not session.context:
        _READERS[key] = HttpReader(session.context, session.site["url"])
    return _READERS[key]


def view_text(fetched: Fetched) -> str:
    """A fetched page in the format of SiteSession.look (header lines, blank line, page text)."""
    return f"URL: {fetched.url}\nTitle: {fetched.title}\n\n{fetched.text}"


def record(session, fetched: Fetched) -> None:
    """Let the session's grounding checks and view keepers see a page read over HTTP as if its tab showed it."""
    session.seen += "\n" + fetched.text
    session.trace.event(session.name, "view", quiet=True, url=fetched.url, text=fetched.text, http=True)
    for sink in session.__dict__.get("view_sinks", ()):
        sink(fetched.url, fetched.text)


async def fetch_view(session, url: str) -> str | None:
    """The page at `url` read over HTTP and recorded for the session, or None when the browser has to open it."""
    rd = reader(session)
    try:
        fetched = await rd.fetch(url)
    except Miss as miss:
        rd.stats["missed"] += 1
        session.trace.event(session.name, "http_miss", url=url[:160], why=str(miss)[:120])
        return None
    except Exception as error:  # never let the reader break a worker: the browser takes over
        rd.stats["missed"] += 1
        session.trace.event(session.name, "http_miss", url=url[:160], why=f"{type(error).__name__}: {str(error)[:100]}")
        return None
    record(session, fetched)
    session.trace.event(session.name, "http_read", url=url[:160], seconds=round(fetched.seconds, 2),
                        chars=len(fetched.text))
    return view_text(fetched)


async def fetch_many(session, urls: list[str]) -> dict[str, str | None]:
    """Several model-chosen pages at once (in their order); None for each page the browser has to open."""
    urls = list(dict.fromkeys(urls))
    views = await asyncio.gather(*(fetch_view(session, u) for u in urls))
    return dict(zip(urls, views))


def stats_line() -> str:
    """Totals over every reader of the run, for the run summary."""
    total = {"fetched": 0, "cached": 0, "missed": 0, "seconds": 0.0}
    for rd in _READERS.values():
        for k in total:
            total[k] += rd.stats[k]
    if not any(total.values()):
        return ""
    mean = total["seconds"] / total["fetched"] if total["fetched"] else 0.0
    return (f"http_read: {total['fetched']} pages fetched (mean {mean:.2f} s), {total['cached']} from cache, "
            f"{total['missed']} handed to the browser")

